  if not oldp.exists():continue
  old=json.loads(oldp.read_text()); img=cv2.imread(str(pth));pr=pre.preprocess_image(img);new=s.detect_spots(pr)
  if old['quality_status']=='REJECT':continue
  occ=new.hair_occlusion_mask
