  for o in old['spot_locations']:
   x=int(round(o['centroid'][0]));y=int(round(o['centroid'][1]));
   if 0<=y<occ.shape[0] and 0<=x<occ.shape[1] and occ[y,x]==0: eligible.append(o)
  matched=0
  for o in eligible:
   if any(math.dist(o['centroid'],n['centroid'])<=8 for n in new.spot_locations):matched+=1
  retention=matched/max(len(eligible),1)
  print(pth.name,'old',old['spot_count'],'new',new.spot_count,'eligible',len(eligible),'matched',matched,'ret',round(retention,3),'hairfiltered',new.hair_filtered_count)
